window.docContents[112].resolve({"/Ju___zos-e-dom___nios/Ju___zos-est___ticos/#Core-C_________-sem___ntica-natural--Ju___zos-e-dom___nios--Ju___zos-est___ticos":{"contents":"O juízo  diz que a expressão  tem tipo  no contexto . Uma regra por construtor de Expr.\n\nO juízo  vale para as expressões que denotam posição. No subconjunto atual, só a variável.\n\nO juízo  diz que o comando  está bem tipado e estende  para , de modo que uma declaração alcança os comandos seguintes da sequência. O tipo de retorno  da função envolvente é um parâmetro implícito.\n\n","context":"Core C++, semântica natural\u0009Juízos e domínios","header":"1.2. Juízos estáticos","id":"/Ju___zos-e-dom___nios/Ju___zos-est___ticos/#Core-C_________-sem___ntica-natural--Ju___zos-e-dom___nios--Ju___zos-est___ticos"}});